package dashboard.enterprise.agent.connector.provider.jira;
import com.fasterxml.jackson.databind.JsonNode; import dashboard.enterprise.agent.connector.credential.CredentialResolver; import dashboard.enterprise.agent.connector.model.*; import dashboard.enterprise.agent.connector.provider.AbstractLiveRestConnectorProvider; import dashboard.enterprise.agent.integration.work.model.WorkItem;
import java.net.http.HttpRequest; import java.nio.charset.StandardCharsets; import java.util.*;
public final class JiraLiveConnectorProvider extends AbstractLiveRestConnectorProvider {
 public JiraLiveConnectorProvider(String endpoint,CredentialResolver resolver){super(new ConnectorDefinition("mapaf.connector.definition/v1","jira-live","Jira Live","JIRA",ConnectorMode.LIVE,List.of("work-item.read","work-item.search","work-item.create-draft"),List.of(new SecretReference("mapaf.connector.secret/v1","email","JIRA_EMAIL"),new SecretReference("mapaf.connector.secret/v1","token","JIRA_API_TOKEN"))),new ConnectorConnection("mapaf.connector.connection/v1","jira-live-connection",endpoint,ConnectorMode.LIVE,Map.of()),90,resolver);}
 protected HttpRequest buildRequest(ConnectorRequest r){String key=String.valueOf(r.parameters().getOrDefault("key","DEMO-1"));String path=switch(r.capabilityId()){case "work-item.read"->"/rest/api/3/issue/"+key;case "work-item.search"->"/rest/api/3/search";case "work-item.create-draft"->"/rest/api/3/issue";default->throw new IllegalArgumentException("Unsupported capability: "+r.capabilityId());};String auth=Base64.getEncoder().encodeToString((secret("email")+":"+secret("token")).getBytes(StandardCharsets.UTF_8));HttpRequest.Builder b=HttpRequest.newBuilder(uri(path)).header("Authorization","Basic "+auth).header("Accept","application/json").header("Content-Type","application/json");return "work-item.create-draft".equals(r.capabilityId())?b.POST(HttpRequest.BodyPublishers.ofString("{}" )).build():b.GET().build();}
 protected Map<String,Object> normalize(String capability,JsonNode n){if("work-item.read".equals(capability)){JsonNode f=n.path("fields");WorkItem item=new WorkItem("mapaf.work-item/v1","jira",n.path("id").asText(),n.path("key").asText(),f.path("summary").asText(),f.path("description").toString(),List.of(),f.path("issuetype").path("name").asText(),f.path("status").path("name").asText(),f.path("priority").path("name").asText(),List.of(),f.path("assignee").path("displayName").asText(),"",n.path("self").asText());return Map.of("workItem",item);}return Map.of("payload",MAPPER.convertValue(n,Map.class));}}
